-- distritos: limite oficial (união dos setores do distrito), dentro da área de ponderação que os contém
update iara.territories set parent_id = 201, source = 'IBGE — Censo Demográfico 2022: limite do distrito (união dos setores censitários)', confidence_status = 'PUBLIC_OFFICIAL',
  geom = (select extensions.st_multi(extensions.st_collectionextract(extensions.st_union(extensions.st_buffer(s.geom::extensions.geometry, 0)), 3))::extensions.geography
          from iara.setores_censitarios s where s.distrito = 'Iguatemi')
where tenant_id = 1 and code = 'IGUATEMI' and kind = 'DISTRITO';
update iara.territories set parent_id = 201, source = 'IBGE — Censo Demográfico 2022: limite do distrito (união dos setores censitários)', confidence_status = 'PUBLIC_OFFICIAL',
